function chartCanvas(canvasId,height){const canvas=$(canvasId);if(!canvas)return null;const width=Math.max(320,canvas.clientWidth||600),scale=devicePixelRatio||1,ctx=canvas.getContext('2d');canvas.width=width*scale;canvas.height=height*scale;ctx.setTransform(scale,0,0,scale,0,0);ctx.clearRect(0,0,width,height);ctx.font='11px Inter, sans-serif';return{canvas,ctx,width,height}}
