function renderLabHistory(){const rows=state.labHistory||[],node=$('labHistoryList');if(!node)return;node.classList.toggle('empty',!rows.length);node.innerHTML=rows.length?rows.map(row=>`<button class="history-row" data-lab-sample="${row.sample_id}"><span><b>${esc(row.sample_name)}</b><small>${esc(row.sample_type)} · ${esc(row.laboratory||'Laboratory not recorded')} · ${row.result_count} results</small><small>${esc(row.results_summary||'')}</small></span><time>${new Date(`${row.lab_date}T12:00:00`).toLocaleDateString()}</time></button>`).join(''):'No laboratory history.';document.querySelectorAll('[data-lab-sample]').forEach(button=>button.onclick=()=>openLabSample(button.dataset.labSample))}
async function openLabSample(id){try{const detail=await api(`api/v1/labs/samples/${id}`),review=detail.review||{},comparison=new Map((detail.comparison||[]).map(row=>[row.result_id,row]));$('labDialogTitle').textContent=detail.sample.sample_name;$('labDetail').innerHTML=`<p class="safety-note">${esc(detail.sample.sample_type)} · ${detail.sample.lab_date?new Date(`${detail.sample.lab_date}T12:00:00`).toLocaleDateString():''} · ${esc(detail.sample.laboratory||'Laboratory not recorded')}</p>`+detail.results.map(result=>{const c=comparison.get(result.id)||{},range=c.target_min!=null||c.target_max!=null?`Target ${c.target_min??'—'}–${c.target_max??'—'} ${c.unit||''}`:'No approved target range';return`<div class="lab-result-row flag-${esc(c.comparison_flag||'normal')}"><div><b>${esc(result.analyte_name)}</b><small>${esc(range)}${c.source_reference?' · '+esc(c.source_reference):''}</small></div><strong>${esc(result.numeric_value??result.text_value??'—')} ${esc(result.unit||'')}<small>${esc(c.comparison_flag||'not compared')}</small></strong>${state.session?.permissions?.write?`<button data-edit-result="${result.id}" data-value="${esc(result.numeric_value??'')}" data-unit="${esc(result.unit||'')}">Correct</button>`:''}</div>`}).join('')+(state.session?.permissions?.write?`<form id="labReviewForm" class="panel lab-review-form"><h3>Decision and follow-up</h3><div class="field-row"><label class="field">Status<select name="review_status"><option value="reviewing">Reviewing</option><option value="decision_needed">Decision needed</option><option value="monitoring">Monitoring</option><option value="closed">Closed</option></select></label><label class="field">Owner<input name="owner_text" value="${esc(review.owner_text||'')}"></label></div><label class="field">Interpretation<textarea name="interpretation">${esc(review.interpretation||'')}</textarea></label><label class="field">Decision / next action<textarea name="decision_action">${esc(review.decision_action||'')}</textarea></label><div class="field-row"><label class="field">Next check<input type="datetime-local" name="next_check_at"></label><label class="field checkbox-field"><input type="checkbox" name="enologist_approval_required" ${review.enologist_approval_required!==0?'checked':''}> Enologist approval required</label></div><div class="dialog-actions"><button type="submit">Save review</button></div></form>`:'')+(detail.revisions.length?`<details><summary>Correction history (${detail.revisions.length})</summary>${detail.revisions.map(r=>`<p><b>${esc(r.changed_by)}</b> · ${new Date(r.changed_at).toLocaleString()}<br>${esc(r.reason)}</p>`).join('')}</details>`:'');if(review.review_status&&$('labReviewForm'))$('labReviewForm').elements.review_status.value=review.review_status;if(review.next_check_at&&$('labReviewForm'))$('labReviewForm').elements.next_check_at.value=String(review.next_check_at).slice(0,16);$('labDialog').showModal();document.querySelectorAll('[data-edit-result]').forEach(button=>button.onclick=()=>correctLabResult(button,id));if($('labReviewForm'))$('labReviewForm').onsubmit=async event=>{event.preventDefault();const form=new FormData(event.target),payload=Object.fromEntries(form.entries());payload.enologist_approval_required=event.target.elements.enologist_approval_required.checked;for(const key of Object.keys(payload))if(payload[key]==='')payload[key]=null;try{await api(`api/v1/labs/${id}/review`,{method:'POST',body:JSON.stringify(payload)});toast('Lab decision saved');$('labDialog').close();await loadAll()}catch(error){toast(error.message)}}}catch(error){toast(error.message)}}
async function correctLabResult(button,sampleId){const value=prompt('Correct numeric value',button.dataset.value);if(value===null)return;const unit=prompt('Unit',button.dataset.unit);if(unit===null)return;const reason=prompt('Why is this being corrected?');if(!reason)return toast('A correction reason is required');try{await api(`api/v1/labs/results/${button.dataset.editResult}`,{method:'PATCH',body:JSON.stringify({numeric_value:value===''?null:Number(value),unit,reason})});toast('Correction saved with audit history');await openLabSample(sampleId);await loadAll()}catch(error){toast(error.message)}}
function drawWeatherComparison(){const measure=$('weatherMeasure')?.value||'temp_avg_c',colors=['#d4af37','#4f7d5b','#a85343','#597da1','#8e6496'],groups={};for(const row of state.weatherComparison||[]){groups[row.weather_year]??=Array(12).fill(null);groups[row.weather_year][Number(row.weather_month)-1]=row[measure]==null?null:Number(row[measure])}const series=Object.entries(groups).map(([name,values])=>({name,values}));$('weatherLegend').innerHTML=series.map((s,i)=>`<span><i style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${colors[i%colors.length]};margin-right:4px"></i>${s.name}</span>`).join('');lineChart('weatherCompareChart',series,colors,240)}
async function openRecords(type){try{const rows=await api(`api/v1/records/${type}`);$('recordDialogTitle').textContent=type[0].toUpperCase()+type.slice(1);$('recordDialogList').innerHTML=type==='attachments'?(rows.length?rows.map(row=>`<a class="attachment-card" href="api/v1/attachments/${row.id}/file" target="_blank" rel="noopener"><span class="attachment-preview">${String(row.media_type||'').startsWith('image/')?`<img src="api/v1/attachments/${row.id}/file" alt="${esc(row.caption||row.original_filename)}" loading="lazy">`:'PDF'}</span><span><b>${esc(row.caption||row.original_filename)}</b><small>${esc(row.entity_type.replaceAll('_',' '))} · ${esc(row.uploaded_by||'unknown')} · ${new Date(row.created_at).toLocaleDateString()}</small></span></a>`).join(''):'<div class="list empty">No photo evidence.</div>'):(rows.length?rows.map(row=>`<div class="record-data-row">${Object.entries(row).filter(([,value])=>value!==null&&value!=='').map(([key,value])=>`<span><small>${esc(key.replaceAll('_',' '))}</small><b>${esc(value)}</b></span>`).join('')}</div>`).join(''):'<div class="list empty">No records.</div>');$('recordDialog').showModal()}catch(error){toast(error.message)}}
