fields.equipment=()=>`<div class="field-row"><div class="field"><label>Date</label><input type="date" name="event_date" required value="${today()}"></div><div class="field"><label>Equipment</label><input name="asset_name" required placeholder="Sprayer, press, pump…"></div></div><div class="field-row"><div class="field"><label>Status before use</label><select name="pre_use_status"><option>Ready</option><option>Hold</option><option>Maintenance</option></select></div><div class="field"><label><input type="checkbox" name="released"> Clean and released</label></div></div><div class="field"><label>Cleaning or maintenance done</label><textarea name="maintenance_action"></textarea></div><details><summary>More details</summary><div class="field"><label>Sanitation method</label><input name="sanitation_method"></div><div class="field-row"><div class="field"><label>Released by</label><input name="released_by"></div><div class="field"><label>Next due</label><input type="date" name="next_due_date"></div></div></details><div class="field"><label>Notes</label><textarea name="notes"></textarea></div>`;
function blockField(){return `<div class="field"><label>Block</label><select name="block_id"><option value="">All / none</option>${(state.reference?.blocks||[]).map(b=>`<option value="${b.id}">${esc(b.code)} — ${esc(b.name)}</option>`).join('')}</select></div>`}function categoryField(){return `<div class="field"><label>Category</label><select name="category">${state.reference.categories.map(c=>`<option value="${c}">${c.replace('_',' ')}</option>`).join('')}</select></div>`}
function openEntry(type,draft=null,intakeId=null){state.entry=type;state.intakeItemId=intakeId;const titles={task:'Plan a task',activity:'Log work',harvest:'Add harvest lot',purchase:'Add purchase invoice',sale:'Add sales invoice',cash:'Record cash movement',cellar:'Cellar operation',cellar_lot:'Start cellar lot',fermentation:'Fermentation check',equipment:'Equipment & sanitation',maturity:'Grape maturity sample',scouting:'Observation',phenology:'Growth stage',treatment:'Treatment record',lab:'Laboratory result',labor:'Labor hours',inventory:'Inventory count',olive:'Olive record',issue:'Issue or decision'},photoTypes=new Set(['activity','harvest','cellar','cellar_lot','fermentation','equipment','maturity','scouting','phenology','treatment','lab','labor','olive','issue']);$('dialogTitle').textContent=titles[type]+(intakeId?' — review AI draft':'');$('formFields').innerHTML=fields[type]()+(!photoTypes.has(type)?'':`<div class="field photo-field"><label>Photos or supporting document (optional)</label><input type="file" name="attachments" accept="image/*,.pdf" multiple><small>Add a field photo, screenshot, instruction, timesheet or report to this record.</small></div>`);if(draft&&typeof draft==='object')for(const[key,value]of Object.entries(draft)){const control=$('entryForm').elements.namedItem(key);if(!control||value==null)continue;if(control.type==='checkbox')control.checked=Boolean(value);else if(control.tagName==='SELECT'&&![...control.options].some(option=>option.value===String(value)))continue;else control.value=Array.isArray(value)?value.join('\n'):String(value)}$('entryDialog').showModal()}
function closeEntry(){if($('entryDialog').open)$('entryDialog').close('cancel')}
async function saveEntry(event){event.preventDefault();const form=new FormData(event.target),attachments=form.getAll('attachments').filter(file=>file instanceof File&&file.size);form.delete('attachments');const payload=Object.fromEntries(form.entries());for(const box of event.target.querySelectorAll('input[type=checkbox]'))payload[box.name]=box.checked;for(const key of Object.keys(payload))if(payload[key]==='')payload[key]=null;['labor_hours','worker_count','weight_kg','gross_kg','tare_kg','crate_count','fruit_temp_c','babo','taxable_amount','vat_amount','withholding_tax','amount_in','amount_out','amount','temp_c','density_sg','brix','ph','ta_g_l','disease_pct','fruit_kg','initial_l','volume_l','quantity','incidence_pct','percent_complete','dose_amount','total_used','phi_days','regular_hours','hourly_rate_eur','quantity_on_hand','olives_harvested_kg','oil_liters','numeric_value'].forEach(key=>{if(payload[key]!=null)payload[key]=Number(payload[key])});const routes={task:'tasks',activity:'activities',harvest:'harvest',purchase:'finance/documents',sale:'finance/documents',cash:'finance/cash',cellar:'quick-entry/cellar_operation',cellar_lot:'quick-entry/cellar_lot',fermentation:'quick-entry/fermentation',equipment:'quick-entry/equipment_event',maturity:'quick-entry/maturity_sample',scouting:'quick-entry/scouting',phenology:'quick-entry/phenology',treatment:'quick-entry/treatment',labor:'quick-entry/labor',inventory:'quick-entry/inventory_count',olive:'quick-entry/olive',issue:'quick-entry/issue'},attachmentTypes={activity:'activity',harvest:'harvest',cellar:'cellar_operation',cellar_lot:'cellar_lot',fermentation:'fermentation',equipment:'equipment_event',maturity:'maturity_sample',scouting:'scouting',phenology:'phenology',treatment:'treatment',lab:'lab_sample',labor:'labor',olive:'olive',issue:'issue'};if(state.entry==='lab'){payload.results=[{analyte_code:payload.analyte_code,analyte_name:payload.analyte_name,numeric_value:payload.numeric_value,unit:payload.unit}];delete payload.analyte_code;delete payload.analyte_name;delete payload.numeric_value;delete payload.unit;routes.lab='lab-samples'}try{const entryType=state.entry,intakeId=state.intakeItemId,saved=await api(`api/v1/${routes[entryType]}?year=${state.year}`,{method:'POST',body:JSON.stringify(payload)});for(const file of attachments){const data=new FormData();data.set('file',file);const response=await fetch(`api/v1/attachments/${attachmentTypes[entryType]}/${saved.id}`,{method:'POST',body:data});if(!response.ok)throw new Error((await response.json().catch(()=>({}))).detail||'Record saved, but a photo could not be attached')}if(intakeId&&attachmentTypes[entryType])await api(`api/v1/intake/${intakeId}/link`,{method:'POST',body:JSON.stringify({entity_type:attachmentTypes[entryType],entity_id:saved.id})});$('entryDialog').close();toast(intakeId?'AI draft reviewed and saved with its source':attachments.length?'Saved with photo evidence':'Saved');loadAll()}catch(error){toast(error.message)}}
async function submitWorkbookImport(commit){const form=$('workbookImportForm'),result=$('workbookImportResult'),data=new FormData(form);if(![...data.values()].some(value=>value instanceof File&&value.size)){toast('Choose at least one workbook');return}if(commit&&!confirm('Import these workbooks into MariaDB now? Continue only because the Home Assistant backup completed successfully.'))return;data.set('commit',commit?'true':'false');data.set('confirmation',commit?'BACKUP VERIFIED':'');result.hidden=false;result.classList.remove('error');result.textContent=commit?'Importing…':'Checking workbooks…';try{const response=await fetch('api/v1/admin/import-workbooks',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||`Import failed (${response.status})`);const lines=[commit?'Import completed.':'Check completed — no database rows changed.'];for(const [name,report] of Object.entries(payload.reports||{})){lines.push(`\n${name.replace('_',' & ')}`);for(const [key,value] of Object.entries(report.counts||{}))lines.push(`${key.replaceAll('_',' ')}: ${value}`);if((report.warnings||[]).length)lines.push(`Warnings: ${report.warnings.join('; ')}`)}result.textContent=lines.join('\n');if(commit)loadAll()}catch(error){result.classList.add('error');result.textContent=error.message}}
function setupAssistantVoice(){const listen=$('assistantListen'),speak=$('assistantSpeak'),form=$('assistantForm'),answer=$('assistantAnswer'),status=$('assistantVoiceStatus'),language=$('assistantLanguage'),Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!listen||!speak||!form||!answer)return;if(!Recognition){listen.disabled=true;status.textContent='Voice input is not supported by this browser; typing still works.'}else{const recognition=new Recognition();recognition.continuous=false;recognition.interimResults=false;listen.onclick=()=>{try{recognition.lang=language?.value==='it'?'it-IT':'en-US';recognition.start();listen.disabled=true;status.textContent=language?.value==='it'?'In ascolto…':'Listening…'}catch{status.textContent='The microphone is already listening.'}};recognition.onresult=event=>{form.elements.question.value=event.results[0][0].transcript;status.textContent=language?.value==='it'?'Domanda acquisita — controlla o premi Chiedi.':'Question captured — review it or press Ask.'};recognition.onerror=event=>{status.textContent=`Microphone: ${event.error||'not available'}`};recognition.onend=()=>{listen.disabled=false}}if(!('speechSynthesis' in window)){speak.disabled=true}else{speak.onclick=()=>{const text=answer.textContent.trim();if(!text)return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=language?.value==='it'?'it-IT':'en-US';speechSynthesis.speak(utterance)}}new MutationObserver(()=>{speak.disabled=!answer.textContent.trim()}).observe(answer,{childList:true,subtree:true,characterData:true})}
async function assistantSubmit(event){event.preventDefault();const answer=$('assistantAnswer'),button=event.submitter,form=new FormData(event.target);button.disabled=true;answer.hidden=false;answer.textContent=$('assistantLanguage')?.value==='it'?'Analisi dei dati del vigneto…':'Reviewing current vineyard data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:form.get('question'),language:$('assistantLanguage')?.value||'en'})});answer.textContent=result.configured?result.answer:result.message}catch(error){answer.textContent=error.message}finally{button.disabled=false}}
function setupContextAI(){document.querySelectorAll('.context-ai-form').forEach(form=>{const answer=form.querySelector('[data-ai-answer]'),status=form.querySelector('[data-ai-status]'),listen=form.querySelector('[data-ai-listen]'),speak=form.querySelector('[data-ai-speak]'),language=form.elements.language,Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){listen.disabled=true;status.textContent='Voice input is not supported here; typing still works.'}else{const recognition=new Recognition();recognition.continuous=false;recognition.interimResults=false;listen.onclick=()=>{recognition.lang=language.value==='it'?'it-IT':'en-US';recognition.start();listen.disabled=true;status.textContent=language.value==='it'?'In ascolto…':'Listening…'};recognition.onresult=event=>{form.elements.question.value=event.results[0][0].transcript;status.textContent=language.value==='it'?'Domanda pronta per la revisione.':'Question ready for review.'};recognition.onerror=event=>{status.textContent=`Microphone: ${event.error||'not available'}`};recognition.onend=()=>{listen.disabled=false}}if(!('speechSynthesis'in window))speak.disabled=true;else speak.onclick=()=>{if(!answer.textContent.trim())return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(answer.textContent);utterance.lang=language.value==='it'?'it-IT':'en-US';speechSynthesis.speak(utterance)};form.onsubmit=async event=>{event.preventDefault();const submit=form.querySelector('[type="submit"]');submit.disabled=true;answer.hidden=false;answer.textContent=language.value==='it'?'Analisi dei dati registrati…':'Reviewing recorded data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:form.elements.question.value,language:language.value,focus:form.dataset.focus})});answer.textContent=result.configured?result.answer:result.message;speak.disabled=!answer.textContent.trim()||!('speechSynthesis'in window)}catch(error){answer.textContent=error.message}finally{submit.disabled=false}}});document.querySelectorAll('[data-ai-prompt]').forEach(button=>button.onclick=()=>{const card=button.closest('.ai-focus-card'),form=card?.querySelector('.context-ai-form');if(form){form.elements.question.value=button.dataset.aiPrompt;form.elements.question.focus()}})}
document.querySelectorAll('.tabs button').forEach(button=>button.onclick=()=>{document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${button.dataset.view}`));if(button.dataset.view==='weather')setTimeout(()=>renderWeather(),0);if(button.dataset.view==='lab')setTimeout(()=>drawLabChart(),0);if(button.dataset.view==='finance')setTimeout(()=>drawFinanceChart(state.finance?.monthly||[]),0)});document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>openEntry(button.dataset.open));document.querySelectorAll('[data-task-filter]').forEach(button=>button.onclick=()=>{state.taskFilter=button.dataset.taskFilter;document.querySelectorAll('[data-task-filter]').forEach(b=>b.classList.toggle('active',b===button));renderTasks()});document.querySelectorAll('[data-close-dialog]').forEach(button=>button.onclick=closeEntry);$('entryDialog')?.addEventListener('click',event=>{if(event.target===$('entryDialog'))closeEntry()});$('entryDialog')?.addEventListener('close',()=>{if($('entryForm'))$('entryForm').reset();if($('formFields'))$('formFields').replaceChildren();state.entry=null;state.intakeItemId=null});if($('entryForm'))$('entryForm').onsubmit=saveEntry;if($('refresh'))$('refresh').onclick=loadAll;if($('todayDate'))$('todayDate').textContent=new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'});document.querySelectorAll('[data-record]').forEach(button=>button.onclick=()=>openRecords(button.dataset.record));document.querySelectorAll('[data-close-record]').forEach(button=>button.onclick=()=>$('recordDialog').close());document.querySelectorAll('[data-close-lab]').forEach(button=>button.onclick=()=>$('labDialog').close());if($('weatherMeasure'))$('weatherMeasure').onchange=drawWeatherComparison;if($('labSearch'))$('labSearch').oninput=()=>{const query=$('labSearch').value.trim().toLowerCase();document.querySelectorAll('[data-lab-sample]').forEach(node=>node.hidden=!node.textContent.toLowerCase().includes(query))};if($('intakeForm'))$('intakeForm').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.target);try{const response=await fetch('api/v1/intake/upload',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Upload failed');toast('Uploaded to the review inbox');event.target.reset();await loadAll()}catch(error){toast(error.message)}};if($('assistantForm'))$('assistantForm').onsubmit=async event=>{event.preventDefault();const answer=$('assistantAnswer'),button=event.submitter;button.disabled=true;answer.hidden=false;answer.textContent='Reviewing current vineyard data…';try{const result=await api('api/v1/assistant/ask',{method:'POST',body:JSON.stringify({question:new FormData(event.target).get('question')})});answer.textContent=result.configured?result.answer:result.message}catch(error){answer.textContent=error.message}finally{button.disabled=false}};if($('weatherImportForm'))$('weatherImportForm').onsubmit=async event=>{event.preventDefault();const status=$('weatherImportStatus'),data=new FormData(event.target);status.textContent='Importing weather history…';try{const response=await fetch('api/v1/weather/import-history',{method:'POST',body:data});const payload=await response.json().catch(()=>({}));if(!response.ok)throw new Error(payload.detail||'Weather import failed');status.textContent=`Imported ${payload.imported} daily records; ${payload.skipped} non-data rows skipped.`;event.target.reset();await loadAll()}catch(error){status.textContent=error.message}};if($('pullFatture'))$('pullFatture').onclick=async()=>{const button=$('pullFatture');button.disabled=true;$('fattureStatus').textContent='Pulling authoritative records…';try{const result=await api('api/v1/finance/fattureincloud/pull',{method:'POST',body:'{}'});$('fattureStatus').textContent=result.configured?`Updated: ${Object.values(result.counts).reduce((a,b)=>a+b,0)} records checked`:result.message;if(result.configured)await loadAll()}catch(error){$('fattureStatus').textContent=error.message}finally{button.disabled=false}};setupYears();loadAll();
document.querySelectorAll('.tabs button').forEach(button=>button.addEventListener('click',()=>{const view=button.dataset.view;if(view==='lab')setTimeout(()=>{drawLabChart();renderLabTrends()},0);if(view==='harvest')setTimeout(()=>renderGrapes(),0);if(view==='projections')setTimeout(()=>renderProjections(),0);if(view==='olives')setTimeout(()=>renderOlives(),0);if(view==='history')setTimeout(()=>renderHistory(),0)}));
if($('checkWorkbooks'))$('checkWorkbooks').onclick=()=>submitWorkbookImport(false);if($('commitWorkbooks'))$('commitWorkbooks').onclick=()=>submitWorkbookImport(true);setupAssistantVoice();setupContextAI();if($('assistantForm'))$('assistantForm').onsubmit=assistantSubmit;if($('projectionMeasure'))$('projectionMeasure').onchange=renderProjections;if($('oliveMeasure'))$('oliveMeasure').onchange=renderOlives;if($('historyMeasure'))$('historyMeasure').onchange=renderHistory;document.querySelectorAll('[data-close-intake]').forEach(button=>button.onclick=()=>$('intakeDialog').close());if($('rejectIntake'))$('rejectIntake').onclick=async()=>{if(!state.intakeItemId)return $('intakeDialog').close();try{await api(`api/v1/intake/${state.intakeItemId}/review`,{method:'PATCH',body:JSON.stringify({review_status:'rejected'})});$('intakeDialog').close();toast('Incoming item rejected');await loadAll()}catch(error){toast(error.message)}};
function renderGrapeLots(){const g=state.grapes||{},harvest=g.harvest_lots||[],cellar=g.cellar_lots||[],hn=$('grapeHarvestLots'),cn=$('grapeCellarLots');if(hn){hn.classList.toggle('empty',!harvest.length);hn.innerHTML=harvest.length?harvest.map(row=>`<details class="treatment-row"><summary><span class="list-icon">🍇</span><span><b>${esc(row.variety_name)} · ${known(row.weight_kg,' kg')}</b><small>${esc(row.block_code||'Block not recorded')} · ${esc(row.destination||'Destination not recorded')} · ${esc(row.condition_grade||'condition not recorded')}</small></span><time>${new Date(row.harvested_at).toLocaleDateString()}</time></summary><div class="treatment-detail"><p><b>Crates:</b> ${known(row.crate_count)}${row.avg_crate_kg?' · '+fmt(row.avg_crate_kg)+' kg average':''}</p><p><b>Maturity:</b> °Babo ${known(row.babo)} · Brix ${known(row.brix)} · pH ${known(row.ph)} · TA ${known(row.ta_g_l,' g/L')}</p><p><b>Notes:</b> ${esc(row.notes||'None')}</p></div></details>`).join(''):`No detailed harvest lots for ${state.year}.`;}if(cn){cn.classList.toggle('empty',!cellar.length);cn.innerHTML=cellar.length?cellar.map(row=>`<details class="treatment-row"><summary><span class="list-icon">◇</span><span><b>${esc(row.code)} — ${esc(row.name)}</b><small>${esc(row.variety_summary||'Blend not recorded')} · ${esc(row.stage)} · ${esc(row.container_code||row.container_name||'container not recorded')}</small></span><time>${known(row.volume_l,' L')}</time></summary><div class="treatment-detail"><p><b>Blend / varieties:</b> ${esc(row.variety_summary||'Not recorded')}</p><p><b>Fruit and yield:</b> ${known(row.fruit_kg,' kg fruit')} · ${known(row.initial_l,' L initial')} · ${known(row.free_run_l,' L free run')} · ${known(row.press_l,' L press')} · ${known(row.loss_l,' L loss')}</p><p><b>Source harvest:</b> ${esc(row.harvest_lot_reference||'Not linked')} · <b>Responsible:</b> ${esc(row.responsible||'Not recorded')}</p><p><b>Notes:</b> ${esc(row.notes||'None')}</p></div></details>`).join(''):`No blend or cellar-lot details for ${state.year}.`;}}
if($('checkGmail'))$('checkGmail').onclick=async()=>{const button=$('checkGmail'),status=$('gmailStatus');button.disabled=true;status.textContent='Checking Gmail…';try{const result=await api('api/v1/intake/gmail/check',{method:'POST',body:'{}'});status.textContent=result.message;if(result.configured)await loadAll()}catch(error){status.textContent=error.message}finally{button.disabled=false}};
